#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    vector<string> buildArray(vector<int>& target, int n) {
        vector<string> res;
        int i = 1, j = 0;
        while (j < target.size()) {
            res.push_back("Push");
            if (target[j] != i++) res.push_back("Pop");
            else ++j;
        }
        return res;
    }
};
